# ------------------------------------------------------------------ OMS AT WORK
def area(bm, tags, title, kicker, promise, fill, img, brief, what, wrong, layers, you, kpi):
    rows = [[lvl, f"ACE-{c}  {DOCS[c][0]}"] for lvl, c in layers]
    return [("h2pb", title, bm, tags), ("band", kicker, promise, fill), ("ph", img, brief, 2.2),
            ("p", "**What we do.** " + what), ("p", "**What could go wrong.** " + wrong),
            ("table", ["Layer", "How OMS keeps it under control"], rows, [1.5, 5.0], "brand"),
            ("note", you), ("kpi", kpi)]

